<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Walking Alpaca</title>
    <style>
        :root {
            --cycle: 1.6s; /* Full 4-beat walk stride */
            --bob: calc(var(--cycle) / 2);
        }

        html, body {
            margin: 0;
            padding: 0;
            width: 100vw;
            height: 100vh;
            overflow: hidden;
            background: #a0c4ff;
        }

        svg {
            display: block;
            width: 100vw;
            height: 100vh;
        }

        /* --- Performance Hints --- */
        .anim-leg, .anim-knee, #alpaca-bob, #neck-anim, #head-anim, 
        #tail-anim, #bell-anim, .ear-anim, .fringe-anim, #shadow-anim,
        .pan-layer, .mote {
            will-change: transform, opacity;
        }

        /* --- Parallax Background --- */
        @keyframes pan {
            from { transform: translateX(0); }
            to   { transform: translateX(-1280px); }
        }
        .pan-clouds { animation: pan 120s linear infinite; }
        .pan-far    { animation: pan 70s linear infinite; }
        .pan-mid    { animation: pan 35s linear infinite; }
        .pan-near   { animation: pan 18s linear infinite; }
        .pan-grass  { animation: pan 12s linear infinite; }

        /* --- Floating Dust Motes --- */
        @keyframes float {
            0%   { transform: translate(0, 0) scale(1); opacity: 0; }
            20%  { opacity: 0.7; }
            80%  { opacity: 0.7; }
            100% { transform: translate(var(--drift), -180px) scale(0.4); opacity: 0; }
        }
        .mote { animation: float linear infinite; filter: blur(0.5px); }

        /* --- Biomechanical Walk Gait --- */
        /* Upper leg: smooth reach, steady push, quick recovery */
        @keyframes leg-swing {
            0%   { transform: rotate(18deg); }
            12%  { transform: rotate(11deg); }
            25%  { transform: rotate(2deg); }
            37%  { transform: rotate(-7deg); }
            50%  { transform: rotate(-16deg); }
            60%  { transform: rotate(-12deg); }
            75%  { transform: rotate(2deg); }
            90%  { transform: rotate(15deg); }
            100% { transform: rotate(18deg); }
        }
        /* Lower leg: folds up only during forward recovery to clear ground */
        @keyframes knee-bend {
            0%, 45% { transform: rotate(0deg); }
            60%     { transform: rotate(-28deg); }
            80%     { transform: rotate(-10deg); }
            100%    { transform: rotate(0deg); }
        }

        .anim-leg  { animation: leg-swing var(--cycle) linear infinite; }
        .anim-knee { animation: knee-bend var(--cycle) linear infinite; }

        /* 4-Beat Sequence: LH -> LF -> RH -> RF (Negative delays start mid-cycle instantly) */
        #leg-bl .anim-leg, #leg-bl .anim-knee { animation-delay: 0s; }
        #leg-fl .anim-leg, #leg-fl .anim-knee { animation-delay: -0.4s; }
        #leg-br .anim-leg, #leg-br .anim-knee { animation-delay: -0.8s; }
        #leg-fr .anim-leg, #leg-fr .anim-knee { animation-delay: -1.2s; }

        /* Depth cue for far-side legs */
        .far-leg { filter: brightness(0.86) saturate(0.85); }

        /* --- Secondary Motion --- */
        @keyframes bob {
            0%, 100% { transform: translateY(1px) rotate(0deg); }
            25%      { transform: translateY(-4px) rotate(0.5deg); }
            50%      { transform: translateY(2px) rotate(0deg); }
            75%      { transform: translateY(-4px) rotate(-0.5deg); }
        }
        #alpaca-bob { animation: bob var(--bob) ease-in-out infinite; }

        @keyframes nod {
            0%, 100% { transform: rotate(1.5deg); }
            25%, 75% { transform: rotate(-1.5deg); }
            50%      { transform: rotate(2deg); }
        }
        #neck-anim { animation: nod var(--bob) ease-in-out infinite; }
        #head-anim { animation: nod var(--bob) ease-in-out infinite reverse; }

        @keyframes swish {
            0%, 100% { transform: rotate(-6deg); }
            50%      { transform: rotate(8deg); }
        }
        #tail-anim { animation: swish var(--bob) ease-in-out infinite; }

        @keyframes swing {
            0%, 100% { transform: rotate(12deg); }
            50%      { transform: rotate(-12deg); }
        }
        #bell-anim { animation: swing var(--bob) ease-in-out infinite; }

        @keyframes fringe {
            0%, 100% { transform: rotate(0deg); }
            50%      { transform: rotate(-3deg); }
        }
        .fringe-anim { animation: fringe var(--bob) ease-in-out infinite; }

        @keyframes twitch {
            0%, 80%, 100% { transform: rotate(0deg); }
            86%           { transform: rotate(-7deg); }
            93%           { transform: rotate(4deg); }
        }
        .ear-anim { animation: twitch 3.2s ease-in-out infinite; }

        @keyframes shadow-pulse {
            0%, 50%, 100% { transform: scale(1.02); opacity: 0.18; }
            25%, 75%      { transform: scale(0.95); opacity: 0.11; }
        }
        #shadow-anim { animation: shadow-pulse var(--bob) ease-in-out infinite; }
    </style>
</head>
