<script>
    // Generate subtle atmospheric dust motes purely in-code
    document.addEventListener("DOMContentLoaded", () => {
        const container = document.getElementById('motes');
        let markup = '';
        for (let i = 0; i < 35; i++) {
            const x = Math.random() * 1280;
            const y = 320 + Math.random() * 350;
            const r = 0.8 + Math.random() * 2.2;
            const dur = 5 + Math.random() * 8;
            const del = -Math.random() * 15;
            const drift = -40 - Math.random() * 140;
            markup += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.toFixed(1)}" fill="#ffffff" class="mote" style="animation-duration:${dur.toFixed(1)}s; animation-delay:${del.toFixed(1)}s; --drift:${drift.toFixed(1)}px"/>`;
        }
        container.innerHTML = markup;
    });
</script>

